import React, { useState, useEffect } from 'react';
import { getFranchises } from '../services/api'; // Assuming you have `getFranchises` function

const ExamData = () => {
  const [filterFranchiseId, setFilterFranchiseId] = useState(''); // State to store the selected filter
  const [franchises, setFranchises] = useState([]); // Store the list of franchises
  const [examDataList, setExamDataList] = useState([]); // Store the list of exam data

  // Fetch franchises on component mount
  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises(); 
        console.log(response.data)
        setFranchises(response.data); // Assuming the response contains an array of franchises
      } catch (error) {
        console.error('Error fetching franchises:', error);
        alert('Failed to fetch franchises');
      }
    };

    fetchFranchises();
  }, []); // Run once when the component mounts

  // Filter exam data based on selected franchise
  const filteredExamData = filterFranchiseId
    ? examDataList.filter((exam) => exam.franchiseId === filterFranchiseId)
    : examDataList;

  const getFranchiseName = (id) => {
    const franchise = franchises.find((f) => f._id === id);
    return franchise ? franchise.name : 'Unknown Franchise';
  };

  return (
    <div>
      <h1>Manage Exam Data</h1>

      {/* Franchise filter dropdown */}
      <div>
        <label htmlFor="filterFranchiseId">Filter by Franchise:</label>
        <select
          id="filterFranchiseId"
          name="filterFranchiseId"
          value={filterFranchiseId}
          onChange={(e) => setFilterFranchiseId(e.target.value)}
        >
          <option value="">All</option>
          {franchises.map((franchise) => (
            <option key={franchise._id} value={franchise._id}>
              {franchise.name}
            </option>
          ))}
        </select>
      </div>

      <h2>Exam Data</h2>
      {filteredExamData.length > 0 ? (
        <table border="1">
          <thead>
            <tr>
              <th>Franchise Name</th>
              <th>Exam Name</th>
              <th>Date</th>
              <th>Students Attended</th>
            </tr>
          </thead>
          <tbody>
            {franchise.map((exam, index) => (
              <tr key={index}>
                <td>{getFranchiseName(exam.franchiseId)}</td>
                <td>{exam.examName}</td>
                <td>{exam.date}</td>
                <td>{exam.studentsAttended}</td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <p>No exam data available for the selected franchise.</p>
      )}
    </div>
  );
};

export default ExamData;
